/**
 * Handles setting focus down through the shadow root.
 */
focus() {
  this.#container.focus();
}

/**
 * handles setting focus on the correct element when the notification is
 * focused
 */
focus() {
  this.shadowRoot.querySelector(".in-app-notification-container").focus();
}

add_task(async function test_keyboardShortcut() {
  await showNotification();
  manager.dispatchEvent(
    new KeyboardEvent("keydown", {
      altKey: true,
      shiftKey: true,
      code: "KeyJ",
      bubbles: true,
      composed: true,
    })
  );

  const notification = manager.firstElementChild;

  // The in-app-notification is reported as having focus because the container
  // that really has focus is in the shadow root.
  Assert.equal(
    document.activeElement,
    notification,
    "The notification has focus"
  );

  hideNotification();
